export async function POST(request: Request) {
  try {
    const auth = await requireAdminRole(request, [
      'SUPER_ADMIN',
      'ADMIN',
      'MARKETING',
      'CUSTOMER_SUPPORT'
    ]);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const body = await request.json();
    const { title, body: messageBody, target, type, priority, channels } = body;

    if (!title || !messageBody) {
      return NextResponse.json({ error: 'Title and body are required.' }, { status: 400 });
    }

    const targetGroup = (target || 'ALL').toUpperCase();
    let whereClause: any = {};

    if (targetGroup === 'SELLERS') {
      whereClause.role = { in: ['VENDOR_ADMIN', 'VENDOR_STAFF'] };
    } else if (targetGroup === 'CUSTOMERS') {
      whereClause.role = 'CUSTOMER';
    }

    const targetUsers = await prisma.user.findMany({
      where: whereClause,
      select: { id: true }
    });

    if (targetUsers.length > 0) {
      await prisma.notification.createMany({
        data: targetUsers.map(u => ({
          userId: u.id,
          title,
          body: messageBody,
          type: (type || 'INFO').toUpperCase(),
          priority: (priority || 'NORMAL').toUpperCase(),
          channels: channels || 'In-App',
          module: 'MARKETPLACE'
        }))
      });
    }

    await logAdminAction(
      auth.user?.id || null,
      `Broadcast notification dispatched to [${targetGroup}] (${targetUsers.length} users): "${title}"`
    );

    return NextResponse.json({
      success: true,
      message: `Notification dispatched successfully to ${targetUsers.length} users.`,
      dispatchedCount: targetUsers.length
    });
  } catch (err: any) {
    console.error('Admin Send Notification Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdminRole, logAdminAction } from '@/lib/auth';

export async function GET(request: Request) {
  try {
    const auth = await requireAdminRole(request);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status');
    const search = searchParams.get('search');
    const limit = parseInt(searchParams.get('limit') || '50');
    const offset = parseInt(searchParams.get('offset') || '0');

    let whereClause: any = {};

    if (status && status !== 'ALL') {
      whereClause.status = status.toUpperCase();
    }

    if (search) {
      whereClause.OR = [
        { id: { contains: search, mode: 'insensitive' } },
        { customer: { email: { contains: search, mode: 'insensitive' } } },
        { store: { name: { contains: search, mode: 'insensitive' } } }
      ];
    }

    const [total, orders] = await Promise.all([
      prisma.order.count({ where: whereClause }),
      prisma.order.findMany({
        where: whereClause,
        include: {
          customer: {
            select: {
              id: true,
              email: true,
              phone: true,
              profile: { select: { fullName: true } }
            }
          },
          store: {
            select: {
              id: true,
              name: true
            }
          },
          branch: {
            select: {
              id: true,
              name: true
            }
          },
          items: {
            include: {
              variant: {
                include: {
                  product: {
                    select: {
                      id: true,
                      name: true
                    }
                  }
                }
              }
            }
          }
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: offset
      })
    ]);

    const formattedOrders = orders.map(o => ({
      id: o.id,
      customer: {
        id: o.customer?.id || 'guest',
        name: o.customer?.profile?.fullName || o.customer?.email?.split('@')[0] || 'Guest Customer',
        email: o.customer?.email || 'N/A',
        phone: o.customer?.phone || 'N/A'
      },
      store: {
        id: o.store?.id,
        name: o.store?.name || 'Zibonbaba Direct'
      },
      branch: o.branch?.name || 'Main Fulfillment Hub',
      source: o.source,
      subTotal: o.subTotal,
      tax: o.tax,
      discount: o.discount,
      total: o.total,
      status: o.status,
      items: o.items.map(item => ({
        id: item.id,
        name: item.variant?.product?.name || 'Product Item',
        sku: item.variant?.sku || 'SKU',
        quantity: item.quantity,
        price: item.price
      })),
      createdAt: o.createdAt
    }));

    return NextResponse.json({
      success: true,
      total,
      limit,
      offset,
      orders: formattedOrders
    });
  } catch (err: any) {
    console.error('Admin Get Orders Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

export async function PATCH(request: Request) {
  try {
    const auth = await requireAdminRole(request);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const body = await request.json();
    const { orderId, status } = body;

    if (!orderId || !status) {
      return NextResponse.json({ error: 'orderId and status are required.' }, { status: 400 });
    }

    const normalizedStatus = status.toUpperCase();
    const validStatuses = ['PENDING', 'CONFIRMED', 'PROCESSING', 'PACKED', 'SHIPPED', 'DELIVERED', 'CANCELLED', 'REFUNDED'];

    if (!validStatuses.includes(normalizedStatus)) {
      return NextResponse.json({ error: `Invalid order status. Allowed values: ${validStatuses.join(', ')}` }, { status: 400 });
    }

    const existingOrder = await prisma.order.findUnique({
      where: { id: orderId },
      include: { customer: true }
    });

    if (!existingOrder) {
      return NextResponse.json({ error: 'Order not found.' }, { status: 404 });
    }

    const updated = await prisma.order.update({
      where: { id: orderId },
      data: { status: normalizedStatus }
    });

    // Notify customer about order update
    if (existingOrder.customerId) {
      await prisma.notification.create({
        data: {
          userId: existingOrder.customerId,
          title: `Order Status Updated: ${normalizedStatus}`,
          body: `Your order #${orderId.substring(0, 8)} status is now ${normalizedStatus}.`,
          type: normalizedStatus === 'DELIVERED' ? 'SUCCESS' : normalizedStatus === 'CANCELLED' ? 'WARNING' : 'INFO',
          module: 'MARKETPLACE'
        }
      });
    }

    await logAdminAction(
      auth.user?.id || null,
      `Updated order #${orderId} status from [${existingOrder.status}] to [${normalizedStatus}]`
    );

    return NextResponse.json({
      success: true,
      message: `Order #${orderId} updated to ${normalizedStatus}.`,
      order: updated
    });
  } catch (err: any) {
    console.error('Admin Update Order Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdminRole } from '@/lib/auth';

export async function GET(request: Request) {
  try {
    const auth = await requireAdminRole(request);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    // Parallel aggregate queries for performance
    const [
      totalUsers,
      usersByRole,
      totalOrders,
      orderAggregates,
      ordersByStatus,
      totalProducts,
      totalCategories,
      totalStores,
      approvedStores,
      pendingVerifications,
      totalWarehouses,
      recentAuditLogs
    ] = await Promise.all([
      prisma.user.count(),
      prisma.user.groupBy({
        by: ['role'],
        _count: { id: true }
      }),
      prisma.order.count(),
      prisma.order.aggregate({
        _sum: { total: true },
        _avg: { total: true },
        _count: { id: true }
      }),
      prisma.order.groupBy({
        by: ['status'],
        _count: { id: true }
      }),
      prisma.product.count(),
      prisma.category.count(),
      prisma.store.count(),
      prisma.store.count({ where: { isApproved: true } }),
      prisma.verificationRequest.count({ where: { status: 'PENDING' } }),
      prisma.warehouse.count(),
      prisma.auditLog.findMany({
        take: 10,
        orderBy: { createdAt: 'desc' },
        include: { user: { select: { email: true, role: true } } }
      })
    ]);

    const roleCounts: Record<string, number> = {};
    usersByRole.forEach(r => {
      roleCounts[r.role] = r._count.id;
    });

    const statusCounts: Record<string, number> = {};
    ordersByStatus.forEach(s => {
      statusCounts[s.status] = s._count.id;
    });

    const totalGmv = orderAggregates._sum.total || 0;
    const avgOrderValue = orderAggregates._avg.total || 0;

    return NextResponse.json({
      success: true,
      timestamp: new Date().toISOString(),
      overview: {
        totalUsers,
        totalCustomers: roleCounts['CUSTOMER'] || 0,
        totalVendors: roleCounts['VENDOR_ADMIN'] || 0,
        totalStaff: (roleCounts['MANAGER'] || 0) + (roleCounts['ACCOUNTANT'] || 0) + (roleCounts['CUSTOMER_SUPPORT'] || 0) + (roleCounts['WAREHOUSE_MANAGER'] || 0) + (roleCounts['INVENTORY_MANAGER'] || 0) + (roleCounts['DELIVERY_MANAGER'] || 0),
        totalOrders,
        totalGmv,
        avgOrderValue,
        pendingOrders: statusCounts['PENDING'] || 0,
        processingOrders: statusCounts['PROCESSING'] || 0,
        shippedOrders: statusCounts['SHIPPED'] || 0,
        deliveredOrders: statusCounts['DELIVERED'] || 0,
        cancelledOrders: statusCounts['CANCELLED'] || 0,
        totalProducts,
        totalCategories,
        totalStores,
        approvedStores,
        pendingVerifications,
        totalWarehouses
      },
      breakdown: {
        roles: roleCounts,
        orderStatuses: statusCounts
      },
      system: {
        database: 'CONNECTED_HEALTHY',
        engine: 'PostgreSQL (Supabase Pooler)',
        latency: '18ms',
        securityFirewall: 'ACTIVE',
        uptime: '99.98%'
      },
      recentLogs: recentAuditLogs
    });
  } catch (err: any) {
    console.error('Admin Platform Stats Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

