import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdminRole, logAdminAction } from '@/lib/auth';
import bcrypt from 'bcryptjs';

export async function GET(request: Request) {
  try {
    const auth = await requireAdminRole(request);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const { searchParams } = new URL(request.url);
    const role = searchParams.get('role');
    const status = searchParams.get('status');
    const search = searchParams.get('search');
    const limit = parseInt(searchParams.get('limit') || '50');
    const offset = parseInt(searchParams.get('offset') || '0');

    let whereClause: any = {};

    if (role && role !== 'ALL') {
      whereClause.role = role.toUpperCase();
    }

    if (status && status !== 'ALL') {
      whereClause.status = status.toUpperCase();
    }

    if (search) {
      whereClause.OR = [
        { email: { contains: search, mode: 'insensitive' } },
        { phone: { contains: search } },
        { profile: { fullName: { contains: search, mode: 'insensitive' } } }
      ];
    }

    const [total, users] = await Promise.all([
      prisma.user.count({ where: whereClause }),
      prisma.user.findMany({
        where: whereClause,
        include: {
          profile: true,
          stores: { select: { id: true, name: true, isApproved: true } },
          _count: { select: { orders: true } }
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: offset
      })
    ]);

    const formattedUsers = users.map(u => ({
      id: u.id,
      email: u.email,
      phone: u.phone || 'N/A',
      name: u.profile?.fullName || u.email.split('@')[0],
      role: u.role,
      status: u.status,
      ordersCount: u._count.orders,
      stores: u.stores,
      walletBalance: u.walletBalance,
      loyaltyPoints: u.loyaltyPoints,
      createdAt: u.createdAt
    }));

    return NextResponse.json({
      success: true,
      total,
      limit,
      offset,
      users: formattedUsers
    });
  } catch (err: any) {
    console.error('Admin Get Users Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const auth = await requireAdminRole(request, ['SUPER_ADMIN', 'ADMIN']);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const body = await request.json();
    const { email, password, fullName, phone, role, status } = body;

    if (!email || !password || !fullName) {
      return NextResponse.json({ error: 'Email, password and full name are required.' }, { status: 400 });
    }

    const cleanEmail = email.trim().toLowerCase();

    // Check if user already exists
    const existing = await prisma.user.findUnique({
      where: { email: cleanEmail }
    });

    if (existing) {
      return NextResponse.json({ error: 'A user account with this email already exists.' }, { status: 409 });
    }

    const passwordHash = await bcrypt.hash(password, 10);
    const assignedRole = (role || 'CUSTOMER').toUpperCase();
    const assignedStatus = (status || 'ACTIVE').toUpperCase();

    const newUser = await prisma.user.create({
      data: {
        email: cleanEmail,
        passwordHash,
        role: assignedRole,
        status: assignedStatus,
        phone: phone || null,
        profile: {
          create: {
            fullName
          }
        }
      },
      include: {
        profile: true
      }
    });

    await logAdminAction(auth.user?.id || null, `Created user account ${cleanEmail} with role [${assignedRole}]`);

    return NextResponse.json({
      success: true,
      message: `User ${cleanEmail} created successfully.`,
      user: {
        id: newUser.id,
        email: newUser.email,
        name: newUser.profile?.fullName,
        role: newUser.role,
        status: newUser.status,
        createdAt: newUser.createdAt
      }
    }, { status: 201 });
  } catch (err: any) {
    console.error('Admin Create User Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdminRole, logAdminAction } from '@/lib/auth';
import bcrypt from 'bcryptjs';

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAdminRole(request);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const { id } = await params;

    const user = await prisma.user.findUnique({
      where: { id },
      include: {
        profile: true,
        stores: true,
        orders: {
          take: 10,
          orderBy: { createdAt: 'desc' },
          include: { items: true }
        },
        loginHistory: {
          take: 10,
          orderBy: { createdAt: 'desc' }
        },
        addresses: true
      }
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found.' }, { status: 404 });
    }

    return NextResponse.json({
      success: true,
      user: {
        id: user.id,
        email: user.email,
        phone: user.phone,
        role: user.role,
        status: user.status,
        name: user.profile?.fullName,
        walletBalance: user.walletBalance,
        loyaltyPoints: user.loyaltyPoints,
        stores: user.stores,
        orders: user.orders,
        loginHistory: user.loginHistory,
        addresses: user.addresses,
        createdAt: user.createdAt
      }
    });
  } catch (err: any) {
    console.error('Admin Get User Details Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAdminRole(request, ['SUPER_ADMIN', 'ADMIN']);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const { id } = await params;
    const body = await request.json();
    const { role, status, fullName, phone, password, suspendedReason } = body;

    const existingUser = await prisma.user.findUnique({
      where: { id },
      include: { profile: true }
    });

    if (!existingUser) {
      return NextResponse.json({ error: 'User not found.' }, { status: 404 });
    }

    // Protect Super Admin account from demotion by non-superadmin
    if (existingUser.role === 'SUPER_ADMIN' && auth.user?.role !== 'SUPER_ADMIN') {
      return NextResponse.json({ error: 'Only Super Administrators can modify Super Admin accounts.' }, { status: 403 });
    }

    let updateData: any = {};
    if (role) updateData.role = role.toUpperCase();
    if (status) {
      updateData.status = status.toUpperCase();
      if (status.toUpperCase() === 'SUSPENDED') {
        updateData.suspendedAt = new Date();
        updateData.suspendedReason = suspendedReason || 'Administrative suspension';
      } else {
        updateData.suspendedAt = null;
        updateData.suspendedReason = null;
      }
    }
    if (phone !== undefined) updateData.phone = phone;
    if (password) {
      updateData.passwordHash = await bcrypt.hash(password, 10);
    }

    const updatedUser = await prisma.user.update({
      where: { id },
      data: {
        ...updateData,
        profile: fullName
          ? {
              upsert: {
                create: { fullName },
                update: { fullName }
              }
            }
          : undefined
      },
      include: { profile: true }
    });

    await logAdminAction(
      auth.user?.id || null,
      `Updated user ${existingUser.email}: status=[${updatedUser.status}], role=[${updatedUser.role}]`
    );

    return NextResponse.json({
      success: true,
      message: `User ${updatedUser.email} updated successfully.`,
      user: {
        id: updatedUser.id,
        email: updatedUser.email,
        name: updatedUser.profile?.fullName,
        role: updatedUser.role,
        status: updatedUser.status,
        phone: updatedUser.phone
      }
    });
  } catch (err: any) {
    console.error('Admin Update User Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAdminRole(request, ['SUPER_ADMIN']);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

