  const allowedRoles = ['VENDOR_ADMIN', 'VENDOR_STAFF', 'ADMIN', 'SUPER_ADMIN'];
  if (!allowedRoles.includes(user.role)) {
    return NextResponse.json({ error: 'Permission denied. Insufficient credentials.' }, { status: 403 });
