import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    if (!id) {
      return NextResponse.json({ error: 'Store ID required.' }, { status: 400 });
    }

    // Lookup store by ID or by name/slug match
    const store = await prisma.store.findFirst({
      where: {
        OR: [
          { id },
          { name: { equals: id, mode: 'insensitive' } }
        ]
      },
      include: {
        owner: {
          select: {
            profile: true
          }
        },
        products: {
          where: { status: 'PUBLISHED' },
          include: {
            category: true,
            variants: {
              include: { inventory: true }
            }
          },
          orderBy: { createdAt: 'desc' }
        }
      }
    });

    if (!store) {
      return NextResponse.json({ error: 'Store not found.' }, { status: 404 });
    }

    const formattedProducts = store.products.map(p => {
      let totalStock = 0;
      p.variants.forEach(v => {
        v.inventory.forEach(inv => {
          totalStock += inv.quantity;
        });
      });
      const firstVariant = p.variants[0];
      return {
        id: p.id,
        name: p.name,
        price: p.basePrice,
        category: p.category?.name || 'General',
        sku: firstVariant?.sku || p.id.slice(0, 8),
        stock: totalStock || 20,
        description: p.description || '',
        vendor: store.name,
        image: 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=600&auto=format&fit=crop&q=80',
        rating: 4.8
      };
    });

    return NextResponse.json({
      store: {
        id: store.id,
        name: store.name,
        description: store.description,
        logo: store.logo,
        banner: store.banner,
        isApproved: store.isApproved,
        commissionRate: store.commissionRate,
        createdAt: store.createdAt,
        ownerName: store.owner?.profile?.fullName || 'Verified Seller'
      },
      products: formattedProducts,
      totalProducts: formattedProducts.length
    });
  } catch (err: any) {
    console.error('Store Public API Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://ikocqacatdvhrameqeox.supabase.co';
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'sb_publishable_qC9hzMB61EWQLVH7flBdXA_GurkO2rd';
const supabase = createClient(supabaseUrl, supabaseAnonKey);

export async function POST(request: Request) {
  try {
    const formData = await request.formData();
    const file = formData.get('file') as File | null;
    const bucket = (formData.get('bucket') as string) || 'products';
    const customFolder = (formData.get('folder') as string) || 'uploads';

    if (!file) {
      return NextResponse.json({ error: 'No file provided' }, { status: 400 });
    }

    // Validate allowed buckets
    const allowedBuckets = ['products', 'avatars', 'stores', 'documents', 'banners'];
    const targetBucket = allowedBuckets.includes(bucket) ? bucket : 'products';

    // Generate unique safe file name
    const timestamp = Date.now();
    const randomStr = Math.random().toString(36).substring(2, 8);
    const sanitizedName = file.name.replace(/[^a-zA-Z0-9._-]/g, '_');
    const filePath = `${customFolder}/${timestamp}_${randomStr}_${sanitizedName}`;

    // Convert file to ArrayBuffer / Buffer for upload
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Upload to Supabase Storage
    const { data, error } = await supabase.storage
      .from(targetBucket)
      .upload(filePath, buffer, {
        contentType: file.type || 'application/octet-stream',
        upsert: true,
      });

    if (error) {
      console.error('Supabase storage upload error:', error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // Get public URL
    const { data: publicUrlData } = supabase.storage
      .from(targetBucket)
      .getPublicUrl(filePath);

    return NextResponse.json({
      success: true,
      url: publicUrlData.publicUrl,
      path: data.path,
      bucket: targetBucket,
      name: file.name,
      size: file.size,
      type: file.type,
    });
  } catch (err: any) {
    console.error('Upload API route error:', err);
    return NextResponse.json(
      { error: err.message || 'Internal server error during upload' },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdminRole, logAdminAction } from '@/lib/auth';

export async function POST(request: Request) {
  try {
    const auth = await requireAdminRole(request);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const body = await request.json();
    const { id, userId, storeId } = body;

    let targetUserId = userId;

    // 1. If it's a verification request record
    if (id && !id.startsWith('store-')) {
      const vr = await prisma.verificationRequest.findUnique({ where: { id } });
      if (vr) {
        targetUserId = vr.userId;
        await prisma.verificationRequest.update({
          where: { id },
          data: {
            status: 'APPROVED',
            reviewedAt: new Date(),
            reviewNote: 'Approved by Administrator.'
          }
        });
      }
    }

    // 2. Approve store if storeId or userId given
    let updatedStore = null;
    if (storeId) {
      updatedStore = await prisma.store.update({
        where: { id: storeId },
        data: { isApproved: true }
      });
    } else if (targetUserId) {
      const userStores = await prisma.store.findMany({ where: { ownerId: targetUserId } });
      for (const st of userStores) {
        await prisma.store.update({
          where: { id: st.id },
          data: { isApproved: true }
        });
      }
      if (userStores.length > 0) updatedStore = userStores[0];
    }

    // 3. Update User status & role to VENDOR_ADMIN if pending
    if (targetUserId) {
      await prisma.user.update({
        where: { id: targetUserId },
        data: {
          status: 'ACTIVE',
          role: 'VENDOR_ADMIN'
        }
      });

      // 4. Create in-app notification for the vendor
      await prisma.notification.create({
        data: {
          userId: targetUserId,
          title: 'Store & KYC Application Approved! 🎉',
          body: 'Congratulations! Your merchant store application and KYC documentation have been reviewed and approved. You may now upload products and start selling.',
          type: 'SUCCESS',
          priority: 'HIGH',
          module: 'MARKETPLACE'
        }
      });
    }

    await logAdminAction(
      auth.user?.id || null,
      `Approved vendor KYC/Store for user [${targetUserId}]`
    );

    return NextResponse.json({
      success: true,
      message: 'Seller verification request approved successfully.',
      store: updatedStore
    });
  } catch (err: any) {
    console.error('Approve Verification Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdminRole } from '@/lib/auth';

export async function GET(request: Request) {
  try {
    const auth = await requireAdminRole(request);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    // 1. Fetch verification requests
    const verifications = await prisma.verificationRequest.findMany({
      where: { status: 'PENDING' },
      include: {
        user: {
          include: {
            profile: true,
            stores: true
          }
        }
      },
      orderBy: { createdAt: 'desc' }
    });

    // 2. Also check unapproved stores
    const unapprovedStores = await prisma.store.findMany({
      where: { isApproved: false },
      include: {
        owner: {
          include: {
            profile: true
          }
        }
      },
      orderBy: { createdAt: 'desc' }
    });

    // Merge or present pending items
    const pendingList = [
      ...verifications.map(v => ({
        id: v.id,
        type: v.type,
        userId: v.userId,
        userName: v.user.profile?.fullName || v.user.email.split('@')[0],
        email: v.user.email,
        phone: v.user.phone || 'N/A',
        storeName: v.user.stores[0]?.name || 'Pending Store Application',
        status: v.status,
        data: v.data,
        createdAt: v.createdAt
      })),
      ...unapprovedStores.map(s => ({
        id: `store-${s.id}`,
        storeId: s.id,
        type: 'TRADE_LICENSE',
        userId: s.ownerId,
        userName: s.owner.profile?.fullName || s.owner.email.split('@')[0],
        email: s.owner.email,
        phone: s.owner.phone || 'N/A',
        storeName: s.name,
        status: 'PENDING',
        data: JSON.stringify({ commissionRate: s.commissionRate, description: s.description }),
        createdAt: s.createdAt
      }))
    ];

    // Remove duplicates if any
    const seen = new Set();
    const uniquePending = pendingList.filter(item => {
      if (seen.has(item.userId)) return false;
      seen.add(item.userId);
      return true;
    });

    return NextResponse.json({
      success: true,
      count: uniquePending.length,
      verifications: uniquePending
    });
  } catch (err: any) {
    console.error('Pending Verifications Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdminRole, logAdminAction } from '@/lib/auth';

export async function POST(request: Request) {
  try {
    const auth = await requireAdminRole(request);
    if (auth.error) {
      return NextResponse.json({ error: auth.error }, { status: auth.status });
    }

    const body = await request.json();
    const { id, userId, reason } = body;

    const reviewReason = reason || 'Documentation submitted did not meet requirements.';
    let targetUserId = userId;

    if (id && !id.startsWith('store-')) {
      const vr = await prisma.verificationRequest.findUnique({ where: { id } });
      if (vr) {
        targetUserId = vr.userId;
        await prisma.verificationRequest.update({
          where: { id },
          data: {
            status: 'REJECTED',
            reviewedAt: new Date(),
            reviewNote: reviewReason
          }
        });
      }
    }

    if (targetUserId) {
      // Create notification for the applicant
      await prisma.notification.create({
        data: {
          userId: targetUserId,
          title: 'Store Verification Update',
          body: `Your verification submission was not approved. Reason: ${reviewReason}. Please update your information and re-apply.`,
          type: 'WARNING',
          priority: 'HIGH',
          module: 'MARKETPLACE'
        }
      });
    }

    await logAdminAction(
      auth.user?.id || null,
      `Rejected verification request for user [${targetUserId}]. Reason: ${reviewReason}`
    );

    return NextResponse.json({
      success: true,
      message: 'Verification request rejected.'
    });
  } catch (err: any) {
    console.error('Reject Verification Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}
